#define MAXN 105
#define MAXC 105

int n, m, c;
int slip[MAXN][MAXC];
long long dp[MAXN][MAXC];

int main() {
    scanf("%d %d %d", &n, &m, &c);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= c; j++)
            scanf("%d", &slip[i][j]);

    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= c; j++)
            dp[i][j] = LLONG_MAX;

    // From bank (row 0) to stones in rows 1..m+1, danger = 0
    for (int i = 1; i <= m + 1 && i <= n; i++)
        for (int j = 1; j <= c; j++)
            dp[i][j] = 0;

    // Fill dp
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= c; j++) {
            if (dp[i][j] == LLONG_MAX) continue;
            // Jump to rows i+1 .. i+m+1
            for (int k = 1; k <= m + 1; k++) {
                int ni = i + k;
                if (ni > n) break;
                for (int l = 1; l <= c; l++) {
                    int hdist = abs(j - l);
                    long long cost = (long long)(slip[i][j] + slip[ni][l]) * hdist;
                    if (dp[i][j] + cost < dp[ni][l])
                        dp[ni][l] = dp[i][j] + cost;
                }
            }
        }
    }

    // Find minimum: stones that can reach opposite bank
    // A stone at row i can reach bank if n - i + 1 <= m + 1, i.e., i >= n - m
    long long ans = LLONG_MAX;
    for (int i = n - m; i <= n; i++) {
        if (i < 1) continue;
        for (int j = 1; j <= c; j++) {
            if (dp[i][j] < ans) ans = dp[i][j];
        }
    }
    // Also check if we can jump directly from bank to bank (n=0 or n <= m+1 with all skips)
    // If n <= m, we can jump directly: danger = 0
    if (n <= m) ans = 0;

    printf("%lld\n", ans);
    return 0;
}

