typedef long long ll;

#define INF ((ll)4e18)

static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int *x = (int *)malloc((n + 1) * sizeof(int));
    int *s = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) {
        scanf("%d %d", &x[i], &s[i]);
    }

    /* dp[i][k]:
       minimum total danger to arrive at stone i having used exactly k skips.
       A jump from row j to row i uses (i-j-1) skips, so only j < i.
       Jump cost between stones:
         (s[j] + s[i]) * abs(x[i] - x[j])
       Jumps from/to bank cost 0.
    */
    ll **dp = (ll **)malloc((n + 1) * sizeof(ll *));
    for (int i = 0; i <= n; i++) {
        dp[i] = (ll *)malloc((m + 1) * sizeof(ll));
        for (int k = 0; k <= m; k++) dp[i][k] = INF;
    }

    /* From starting bank to any stone i:
       can skip i-1 rows before landing on i, cost 0.
    */
    for (int i = 1; i <= n; i++) {
        int need = i - 1;
        if (need <= m) dp[i][need] = 0;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j < i; j++) {
            int used = i - j - 1;
            ll cost = (ll)(s[i] + s[j]) * llabs((ll)x[i] - (ll)x[j]);
            for (int k = 0; k + used <= m; k++) {
                if (dp[j][k] == INF) continue;
                ll cand = dp[j][k] + cost;
                if (cand < dp[i][k + used]) dp[i][k + used] = cand;
            }
        }
    }

    /* From any stone i to ending bank: cost 0, but need to skip n-i rows.
       Also possible to jump directly from starting bank to ending bank if m >= n.
    */
    ll ans = (m >= n ? 0 : INF);
    for (int i = 1; i <= n; i++) {
        int need = n - i;
        for (int k = 0; k + need <= m; k++) {
            ans = minll(ans, dp[i][k]);
        }
    }

    printf("%lld\n", ans);

    for (int i = 0; i <= n; i++) free(dp[i]);
    free(dp);
    free(x);
    free(s);
    return 0;
}

