typedef long long ll;

struct Stone {
    ll row, col, slipperiness;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<vector<Stone>> stones_by_row(n + 1);
    for (int i = 1; i <= n; i++) {
        int k;
        cin >> k;
        for (int j = 0; j < k; j++) {
            ll col, slip;
            cin >> col >> slip;
            stones_by_row[i].push_back({i, col, slip});
        }
    }

    // dp[i][j] = minimum danger to reach stone j in row i
    // We'll use a 1D DP that we update row by row
    vector<vector<ll>> dp(n + 1);

    // Initialize first row
    for (int j = 0; j < (int)stones_by_row[1].size(); j++) {
        dp[1].push_back(0); // Starting from bank has 0 danger
    }

    // For each row i, we want to consider jumps from rows i-m to i-1
    for (int i = 2; i <= n; i++) {
        dp[i].resize(stones_by_row[i].size(), LLONG_MAX);

        // For each stone in current row
        for (int j = 0; j < (int)stones_by_row[i].size(); j++) {
            // Try jumping from previous rows (up to m rows back)
            for (int prev_row = max(1, i - m); prev_row < i; prev_row++) {
                // For each stone in previous row
                for (int k = 0; k < (int)stones_by_row[prev_row].size(); k++) {
                    if (dp[prev_row][k] == LLONG_MAX) continue;

                    ll danger = (stones_by_row[prev_row][k].slipperiness + 
                                stones_by_row[i][j].slipperiness) * 
                               abs(stones_by_row[i][j].col - stones_by_row[prev_row][k].col);

                    dp[i][j] = min(dp[i][j], dp[prev_row][k] + danger);
                }
            }
            // Also consider jumping from bank (if within m rows)
            if (i <= m) {
                dp[i][j] = min(dp[i][j], 0LL); // Bank to stone has 0 danger
            }
        }
    }

    // Answer is minimum danger to reach opposite bank from any stone in last m rows
    ll answer = LLONG_MAX;
    for (int i = max(1, n - m + 1); i <= n; i++) {
        for (int j = 0; j < (int)stones_by_row[i].size(); j++) {
            if (dp[i][j] != LLONG_MAX) {
                answer = min(answer, dp[i][j]);
            }
        }
    }

    // Also consider jumping directly from bank to opposite bank
    if (m >= n + 1) {
        answer = min(answer, 0LL);
    }

    cout << answer << "\n";

    return 0;
}

