const ll INF = (1LL << 62);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> k(n + 1);
    vector<vector<ll>> x(n + 1), s(n + 1);

    for (int i = 1; i <= n; ++i) {
        cin >> k[i];
        x[i].resize(k[i]);
        s[i].resize(k[i]);
        for (int j = 0; j < k[i]; ++j) cin >> x[i][j];
        for (int j = 0; j < k[i]; ++j) cin >> s[i][j];
    }

    // dp[i][j][t]:
    // minimum danger to arrive at stone j in row i,
    // having used exactly t skips in total.
    vector<vector<vector<ll>>> dp(n + 1);
    for (int i = 1; i <= n; ++i) {
        dp[i].assign(k[i], vector<ll>(m + 1, INF));
    }

    // From starting bank to any stone in first (or later) row:
    // bank jumps have danger 0, skipping rows consumes skips.
    for (int i = 1; i <= n; ++i) {
        int skips = i - 1; // skipped rows before landing on row i
        if (skips <= m) {
            for (int j = 0; j < k[i]; ++j) {
                dp[i][j][skips] = 0;
            }
        }
    }

    // Transitions between stones
    for (int i = 1; i <= n; ++i) {
        for (int used = 0; used <= m; ++used) {
            for (int j = 0; j < k[i]; ++j) {
                if (dp[i][j][used] == INF) continue;

                // Jump to row ni > i
                for (int ni = i + 1; ni <= n; ++ni) {
                    int extraSkips = ni - i - 1;
                    if (used + extraSkips > m) break;

                    for (int nj = 0; nj < k[ni]; ++nj) {
                        ll cost = (s[i][j] + s[ni][nj]) * llabs(x[i][j] - x[ni][nj]);
                        ll &ref = dp[ni][nj][used + extraSkips];
                        ref = min(ref, dp[i][j][used] + cost);
                    }
                }
            }
        }
    }

    // Finish by jumping from some stone to the opposite bank with danger 0.
    ll ans = INF;
    for (int i = 1; i <= n; ++i) {
        int needSkipsAfter = n - i; // rows skipped after row i before bank
        for (int used = 0; used <= m; ++used) {
            if (used + needSkipsAfter > m) continue;
            for (int j = 0; j < k[i]; ++j) {
                ans = min(ans, dp[i][j][used]);
            }
        }
    }

    // Direct jump from start bank to end bank is possible only if all rows are skipped.
    if (n <= m) ans = min(ans, 0LL);

    cout << ans << '\n';
    return 0;
}

