import java.io.*;
import java.util.*;

/*
We model rows 1..n, each row has one stone at horizontal position x[i] and slipperiness s[i].
Banks are row 0 and row n+1.

A jump can go from row i to row j where:
- 0 <= i < j <= n+1
- j - i - 1 <= m   (you may skip at most m rows)

Danger:
- 0 if i==0 or j==n+1 (jump from start bank or to end bank)
- otherwise (s[i] + s[j]) * abs(x[i] - x[j])

We need minimum total danger from bank 0 to bank n+1.

DP:
dp[j] = min cost to reach row j (or end bank n+1)
For stone rows j in [1..n]:
  dp[j] = min over i in [max(0, j-m-1) .. j-1]:
            dp[i] + cost(i,j)
where cost(0,j)=0, else (s[i]+s[j])*|x[i]-x[j]|

For end bank:
  ans = min over i in [max(0, n-m) .. n]:
          dp[i]   // because cost(i, n+1)=0

This is O(n*(m+1)), which is the natural solution for the stated constraints style.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        long[] x = new long[n + 1]; // 1..n
        long[] s = new long[n + 1]; // 1..n

        for (int i = 1; i <= n; i++) {
            x[i] = fs.nextLong();
            s[i] = fs.nextLong();
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0; // start bank

        for (int j = 1; j <= n; j++) {
            int from = Math.max(0, j - m - 1);
            long best = INF;
            for (int i = from; i < j; i++) {
                long cand = dp[i];
                if (cand >= INF) continue;
                if (i != 0) {
                    cand += (s[i] + s[j]) * Math.abs(x[i] - x[j]);
                }
                if (cand < best) best = cand;
            }
            dp[j] = best;
        }

        long ans = INF;
        int from = Math.max(0, n - m);
        for (int i = from; i <= n; i++) {
            ans = Math.min(ans, dp[i]); // jump to end bank costs 0
        }

        System.out.println(ans);
    }
}

import sys
from math import inf

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    n, m = int(input_data[idx]), int(input_data[idx+1])
    idx += 2

    # Read grid: n rows, each row has some number of stones
    # Let's figure out columns
    cols = int(input_data[idx]); idx += 1

    grid = []
    for i in range(n):
        row = []
        for j in range(cols):
            row.append(int(input_data[idx])); idx += 1
        grid.append(row)

    # dp[i][j] = min danger to reach stone (i, j)
    dp = [[inf]*cols for _ in range(n)]

    # From bank (row -1) to row i (0 <= i <= m), danger = 0
    for i in range(min(m+1, n)):
        for j in range(cols):
            if grid[i][j] > 0:  # stone exists
                dp[i][j] = 0

    # Fill dp
    for i in range(n):
        for j in range(cols):
            if dp[i][j] == inf:
                continue
            # Jump to rows i+1 to i+m+1
            for ni in range(i+1, min(i+m+2, n)):
                for nj in range(cols):
                    if grid[ni][nj] > 0:
                        danger = (grid[i][j] + grid[ni][nj]) * abs(j - nj)
                        if dp[i][j] + danger < dp[ni][nj]:
                            dp[ni][nj] = dp[i][j] + danger

    # Answer: min dp[i][j] for stones that can reach opposite bank
    ans = inf
    for i in range(n):
        for j in range(cols):
            if dp[i][j] < inf:
                # Can reach opposite bank if n - i <= m + 1
                if n - i <= m + 1:
                    ans = min(ans, dp[i][j])

    if ans == inf:
        print(-1)
    else:
        print(ans)

solve()
